def parse_age(text):
    try:
        age = int(text)
    except ValueError:
        print("not a number:", text)
        return None
    else:
        if age < 0:
            raise ValueError(f"negative age {age}")
        return age
    finally:
        print("checked", text)

print(parse_age("42"))
print(parse_age("abc"))
try:
    parse_age("-5")
except ValueError as e:
    print("caught:", e)

